from pathlib import Path

p = Path('scalp_engine.py')
s = p.read_text(encoding='utf-8')
MARKER = '# KAIROS_SL_ANCHOR_VALID_AT_ENTRY_V1'

if MARKER not in s:
    old = """                violation=next((c for c in m5 if extreme_ts < c.get('t',0) < retest['t'] and\n                                ((c.get('l') is not None and c['l']<=sl) if direction=='LONG'\n                                 else (c.get('h') is not None and c['h']>=sl))),None)\n                if violation is None:\n                    sl_info={'sl':sl,'sl_tf':'M5','sl_classe':'M5_LAST_CAUSAL_SWEEP',\n                             'sl_sweep_ts':extreme_ts,'sl_sweep_extreme':extreme}\n                    sl_audit.update({\n                        'classe':'M5_LAST_CAUSAL_SWEEP','liquidity_level':local_sweep['liquidity_level'],\n                        'liquidity_origin_ts':local_sweep['liquidity_origin_ts'],\n                        'liquidity_confirmed_ts':local_sweep['liquidity_confirmed_ts'],\n                        'sweep_ts':extreme_ts,'sweep_extreme':extreme,\n                        'atr_period':14,'atr_buffer_mult':ATR_BUFFER_MULT,\n                        'atr_value':((extreme-sl)/ATR_BUFFER_MULT if direction=='LONG' and ATR_BUFFER_MULT else\n                                     (sl-extreme)/ATR_BUFFER_MULT if direction=='SHORT' and ATR_BUFFER_MULT else None),\n                        'buffer_abs':abs(float(sl)-float(extreme)),'sl_buffered':sl,\n                        'known_to_entry_last_ts':known_to_entry[-1].get('t') if known_to_entry else None})\n                else:\n                    sl_info=None\n                    sl_audit.update({'motivo':'LAST_CAUSAL_M5_SWEEP_INVALIDADO_ANTES_ENTRY',\n                                     'invalidated_ts':violation.get('t'),'sl_buffered':sl})\n"""
    new = """                # KAIROS_SL_ANCHOR_VALID_AT_ENTRY_V1\n                # O candidato mais recente pode ter sido consumido antes da entry.\n                # Nesse caso nao matamos a tese automaticamente: voltamos, em ordem\n                # causal, ao ultimo sweep M5 do lado correto que AINDA permanecia\n                # protegido no instante da entry. Nenhum candle posterior a entry\n                # participa desta escolha.\n                def _candidate_state_at_entry(cand):\n                    _ext=float(cand['sweep_extreme']); _ts=cand['sweep_ts']\n                    _known=[cc for cc in m5 if cc.get('t',0)<=retest['t']]\n                    _sl=aplicar_buffer_stop_atr(_ext,'alta' if direction=='LONG' else 'baixa',_known)\n                    _side=((_ext < entry) if direction=='LONG' else (_ext > entry))\n                    _viol=next((cc for cc in m5 if _ts < cc.get('t',0) < retest['t'] and\n                                ((cc.get('l') is not None and cc['l']<=_sl) if direction=='LONG'\n                                 else (cc.get('h') is not None and cc['h']>=_sl))),None)\n                    return _side, _sl, _viol, _known\n\n                valid_at_entry=[]\n                for _cand in sl_audit.get('candidatos',[]):\n                    _side,_sl,_viol,_known=_candidate_state_at_entry(_cand)\n                    if _side and _viol is None:\n                        valid_at_entry.append((_cand,_sl,_known))\n                if valid_at_entry:\n                    local_sweep,sl,known_to_entry=max(valid_at_entry,key=lambda x:x[0]['sweep_ts'])\n                    extreme=float(local_sweep['sweep_extreme']); extreme_ts=local_sweep['sweep_ts']\n                    sl_info={'sl':sl,'sl_tf':'M5','sl_classe':'M5_LAST_CAUSAL_SWEEP_VALID_AT_ENTRY',\n                             'sl_sweep_ts':extreme_ts,'sl_sweep_extreme':extreme}\n                    sl_audit.update({\n                        'motivo':'OK_LAST_CAUSAL_M5_SWEEP_VALID_AT_ENTRY',\n                        'classe':'M5_LAST_CAUSAL_SWEEP_VALID_AT_ENTRY',\n                        'liquidity_level':local_sweep['liquidity_level'],\n                        'liquidity_origin_ts':local_sweep['liquidity_origin_ts'],\n                        'liquidity_confirmed_ts':local_sweep['liquidity_confirmed_ts'],\n                        'sweep_ts':extreme_ts,'sweep_extreme':extreme,\n                        'atr_period':14,'atr_buffer_mult':ATR_BUFFER_MULT,\n                        'atr_value':((extreme-sl)/ATR_BUFFER_MULT if direction=='LONG' and ATR_BUFFER_MULT else\n                                     (sl-extreme)/ATR_BUFFER_MULT if direction=='SHORT' and ATR_BUFFER_MULT else None),\n                        'buffer_abs':abs(float(sl)-float(extreme)),'sl_buffered':sl,\n                        'known_to_entry_last_ts':known_to_entry[-1].get('t') if known_to_entry else None,\n                        'valid_candidates_at_entry':len(valid_at_entry)})\n                else:\n                    sl_info=None\n                    _side,_last_sl,_last_viol,_known=_candidate_state_at_entry(local_sweep)\n                    sl_audit.update({'motivo':'SEM_SWEEP_M5_CAUSAL_VALIDO_NA_ENTRY',\n                                     'invalidated_ts':_last_viol.get('t') if _last_viol else None,\n                                     'sl_buffered':_last_sl,'valid_candidates_at_entry':0})\n"""
    if old not in s:
        raise SystemExit('[SL_ANCHOR_PATCH] target block not found')
    s = s.replace(old, new, 1)

p.write_text(s, encoding='utf-8')
compile(s, 'scalp_engine.py', 'exec')
assert MARKER in s
assert 'M5_LAST_CAUSAL_SWEEP_VALID_AT_ENTRY' in s
assert 'SEM_SWEEP_M5_CAUSAL_VALIDO_NA_ENTRY' in s
print('[SL_ANCHOR_PATCH] V1 applied + compile PASS')
